def _hash32(text):
    h=2166136261
    for ch in str(text):
        h=((h^ord(ch))*16777619)&0xffffffff
    return h

def generate_title(genre='melodic-house',mood='uplifting',seed=431207,energy=None):
    bank=TITLE_BANKS.get(str(genre)) or TITLE_BANKS['melodic-house']
    m_bank=MOOD_WORDS.get(str(mood)) or MOOD_WORDS['uplifting']
    first_pool=list(bank['first'])+[w for w in m_bank.get('first',()) if w not in bank['first']]
    second_pool=list(bank['second'])+[w for w in m_bank.get('second',()) if w not in bank['second']]
    s=max(0,int(seed or 0))&0x7fffffff
    e_bucket=int(round(float(energy)*20)) if energy is not None else -1
    h1=_hash32(f'{s}:{genre}:{mood}:{e_bucket}:1')
    h2=_hash32(f'{s}:{genre}:{mood}:{e_bucket}:2')
    w1=first_pool[(s+h1)%len(first_pool)]
    w2=second_pool[((s//7)+h2)%len(second_pool)]
    if w1.lower()[:5]==w2.lower()[:5]:
        w2=second_pool[((s//7)+h2+1)%len(second_pool)]
    return f'{w1} {w2}'
